func lengthOfLIS(nums []int) int {
    n := len(nums)
    dp := make([]int, n)
    res := 1
    for i := range dp {
        dp[i] = 1
        for j := 0; j < i; j++ {
            if nums[j] < nums[i] {
                dp[i] = max(dp[i], dp[j]+1)
            }
        }
        res = max(res, dp[i])
    }
    return res
}

func lengthOfLIS(nums []int) int {
    tails := []int{}
    for _, num := range nums {
        // 二分找第一个 >= num 的位置
        lo, hi := 0, len(tails)
        for lo < hi {
            mid := lo + (hi-lo)/2
            if tails[mid] < num {
                lo = mid + 1
            } else {
                hi = mid
            }
        }
        if lo == len(tails) {
            tails = append(tails, num)
        } else {
            tails[lo] = num
        }
    }
    return len(tails)
}
